_CALLS = []


@command(CommandSpec(Section.UTILITY, Execution.LOAD,
    result=ResultPolicy.SILENT))
def codec_demo(required: int, *, optional: str | None = None,
    enabled: bool = False, mode: Literal["a", "b"] = "a",
