          for result in outputs:
            _present(result)
          # end
        # end
      return outputs
    # end

    result, referenced = _call(model, selected, values, ctx)
    if execution is Execution.LOAD:
      ctx.obj.datasets.extend(_datasets_from_result(result))
      if model.spec.result is ResultPolicy.VALUE:
        _present(result)
